\begin{document}

\section*{প্রাণীর পরিচিতি - কুই মাছ}

\begin{figure}[h]
    \centering
    \includegraphics[width=0.8\textwidth]{path/to/image.png}
    \caption{চিত্র ২.৩.২: কুই মাছের আইশ}
